// Coordinator-only original dependency observer. No copied width algorithm.
package main
import("encoding/json";"os";"github.com/clipperhouse/displaywidth";"github.com/olekukonko/tablewriter/pkg/twwidth")
func main(){var rows []struct{ID string `json:"id"`;Text string `json:"text"`;East bool `json:"east_asian"`;Narrow bool `json:"force_narrow_borders"`;Tab int `json:"tab_width"`};if err:=json.NewDecoder(os.Stdin).Decode(&rows);err!=nil{panic(err)};out:=json.NewEncoder(os.Stdout);for _,row:=range rows{opts:=twwidth.Options{EastAsianWidth:row.East,ForceNarrowBorders:row.Narrow};twwidth.SetOptions(opts);twwidth.SetTabWidth(row.Tab);runes:=[]int{};for _,r:=range row.Text{runes=append(runes,(displaywidth.Options{EastAsianWidth:row.East}).Rune(r))};if err:=out.Encode(map[string]any{"id":row.ID,"text":row.Text,"east_asian":row.East,"force_narrow_borders":row.Narrow,"tab_width":twwidth.TabWidth(),"rune_widths":runes,"width_with_options":twwidth.WidthWithOptions(row.Text,opts),"width_entry":twwidth.Width(row.Text)});err!=nil{panic(err)}}}
